  assert.deepStrictEqual(invoice([{ name: 'Mug', price: '19.99', qty: 3 }]), ['Mug: 59.97', 'Total: 59.97']);
});

test('refund lines print as a normal negative amount', () => {
  assert.deepStrictEqual(
    invoice([{ name: 'Mug', price: '19.99', qty: 1 }, { name: 'Refund', price: '-0.50', qty: 1 }]),
    ['Mug: 19.99', 'Refund: -0.50', 'Total: 19.49'],
  );
});

test('percent discount rounds to the nearest cent', () => {
  assert.deepStrictEqual(
    invoice([{ name: 'Desk', price: '10.05', qty: 1 }], 10),
    ['Desk: 10.05', 'Discount: -1.01', 'Total: 9.04'],
  );
});

